public class Main {
    static int n;
    static long[] a;

    static long atMost(long limit) {
        if (limit < 0) return 0;
        int[] low = new int[n], high = new int[n];  // monotonic deques of indices
        int lh = 0, lt = 0, hh = 0, ht = 0, left = 0;
        long total = 0;
        for (int right = 0; right < n; right++) {
            long v = a[right];
            while (lt > lh && a[low[lt - 1]] >= v) lt--;
            while (ht > hh && a[high[ht - 1]] <= v) ht--;
            low[lt++] = right;
            high[ht++] = right;
            while (a[high[hh]] - a[low[lh]] > limit) {
                if (low[lh] == left) lh++;
                if (high[hh] == left) hh++;
                left++;
            }
            total += right - left + 1;
        }
        return total;
    }

