func atMost(a []int, limit int) int {
	if limit < 0 {
		return 0
	}
	var low, high []int // monotonic deques of indices
	left, total := 0, 0
	for right, v := range a {
		for len(low) > 0 && a[low[len(low)-1]] >= v {
			low = low[:len(low)-1]
		}
		for len(high) > 0 && a[high[len(high)-1]] <= v {
			high = high[:len(high)-1]
		}
		low = append(low, right)
		high = append(high, right)
		for a[high[0]]-a[low[0]] > limit {
			if low[0] == left {
				low = low[1:]
			}
			if high[0] == left {
				high = high[1:]
			}
			left++
		}
		total += right - left + 1
	}
	return total
}

